--
-- Structure de la table `eleve_sante`
--

DROP TABLE IF EXISTS `eleve_sante`;
CREATE TABLE IF NOT EXISTS `eleve_sante` (
  `idSante` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
