--
-- Structure de la table `messages`
--

DROP TABLE IF EXISTS `messages`;
CREATE TABLE IF NOT EXISTS `messages` (
  `idMessages` int UNSIGNED NOT NULL DEFAULT '0',
  `idExp_Pers` int UNSIGNED NOT NULL,
  `idParent` int UNSIGNED NOT NULL,
  `idDest_Pers` int UNSIGNED DEFAULT NULL,
  `direction` enum('admin_to_parent','parent_to_admin') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin_to_parent',
  `objet` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `information` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `type_message` smallint UNSIGNED NOT NULL DEFAULT '0' COMMENT '0 = individuel, 1 = tous les parents, 2 = tous les parents pour paiement',
  `AnneeAcade` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `valider` tinyint UNSIGNED NOT NULL DEFAULT '0',
  `lu` tinyint(1) NOT NULL DEFAULT '0',
  `lu_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idMessages`),
  KEY `mess` (`idParent`),
  KEY `messages_idparent_created_at_index` (`idParent`,`created_at`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

