--
-- Structure de la table `paiement`
--

DROP TABLE IF EXISTS `paiement`;
CREATE TABLE IF NOT EXISTS `paiement` (
  `idPaie` int UNSIGNED NOT NULL,
  `matricule` int UNSIGNED NOT NULL,
  `idAca` int UNSIGNED NOT NULL,
  `montant` double NOT NULL,
  `url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INDEFINI',
  `comentaire` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INDEFINI',
  `idMode` int UNSIGNED NOT NULL DEFAULT '0',
  `operation_ID` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INDEFINI',
  `idPers` int UNSIGNED NOT NULL,
  `datePaie` date NOT NULL,
  `dateEnregistrer` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`idPaie`),
  KEY `enf` (`matricule`),
  KEY `anneepaie` (`idAca`),
  KEY `via` (`idMode`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

