--
-- Structure de la table `paiement_tranches`
--

DROP TABLE IF EXISTS `paiement_tranches`;
CREATE TABLE IF NOT EXISTS `paiement_tranches` (
  `idPaieTranche` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `matricule` int UNSIGNED NOT NULL,
  `idAca` int UNSIGNED NOT NULL,
  `idTranche` int UNSIGNED NOT NULL,
  `idScolarite` int UNSIGNED NOT NULL,
  `ordre` smallint UNSIGNED NOT NULL,
  `statut` enum('en_attente','due','payee','en_retard') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'en_attente',
  `montant_du` double NOT NULL,
  `montant_paye` double NOT NULL DEFAULT '0',
  `date_echeance` date NOT NULL,
  `idPaie` int UNSIGNED DEFAULT NULL,
  `date_paiement` date DEFAULT NULL,
  `idPers` int UNSIGNED DEFAULT NULL,
  `alerte_envoyee` tinyint(1) NOT NULL DEFAULT '0',
  `alerte_envoyee_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idPaieTranche`),
  KEY `paiement_tranches_matricule_idaca_index` (`matricule`,`idAca`),
  KEY `paiement_tranches_statut_date_echeance_index` (`statut`,`date_echeance`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

