--
-- Structure de la table `villenaissance`
--

DROP TABLE IF EXISTS `villenaissance`;
CREATE TABLE IF NOT EXISTS `villenaissance` (
  `idVille` int UNSIGNED NOT NULL,
  `libelle` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Autres',
  `actif` tinyint UNSIGNED NOT NULL DEFAULT '1',
  PRIMARY KEY (`idVille`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

